import { InstrumentEffects } from 'app/services/EffectsService/settings';
import {
  EXPORT_SAMPLE_RATE,
  encodeWav,
} from 'app/services/MelodyExportService/audio';
import { prepareInstrumentSample } from 'app/services/SynthesizerService';
import { createEffectsRack } from 'app/services/SynthesizerService/effects';

import { MAX_EXPORT_BARS } from './beatLibrary';
import { tracksWithHits } from './patterns';
import { DrumSample, sampleKey } from './samples';
import { DrumPlayback } from './transport';
import { decodeDrumClip, getDrumVoice, scheduleDrumVoice } from './voices';

export const createDrumBeatWav = async (
  beat: DrumPlayback,
  effects: InstrumentEffects,
  bars: number,
): Promise<Blob> => {
  if (!Number.isInteger(bars) || bars < 1 || bars > MAX_EXPORT_BARS)
    throw new Error(
      `Enter a whole number of bars from 1 to ${MAX_EXPORT_BARS}.`,
    );
  const tracks = tracksWithHits(beat, beat.steps);
  if (!tracks.length)
    throw new Error('Add a hit on an unmuted row to download a beat.');
  if (!window.OfflineAudioContext) {
    throw new Error('This browser does not support WAV export.');
  }

  let decoder: OfflineAudioContext | undefined;
  const pending = new Map<string, Promise<AudioBuffer>>();
  const load = (sample: DrumSample) => {
    if (sample.kind === 'builtin') return prepareInstrumentSample('drums');
    if (sample.kind === 'instrument')
      return prepareInstrumentSample(sample.timbre);
    const key = sampleKey(sample);
    let buffer = pending.get(key);
    if (!buffer) {
      decoder ??= new OfflineAudioContext(1, 1, EXPORT_SAMPLE_RATE);
      buffer = decodeDrumClip(decoder, sample);
      pending.set(key, buffer);
    }
    return buffer;
  };
  const stepDuration = 60 / beat.bpm / 4;
  const hits = (
    await Promise.all(
      tracks.map(async track => {
        const sample = beat.samples[track];
        const voice = getDrumVoice(sample, await load(sample));
        if (!voice) throw new Error('Could not read a sample in this beat.');
        return beat.pattern[track]
          .slice(0, beat.steps)
          .flatMap((on, step) => (on ? [{ step, voice }] : []));
      }),
    )
  ).flat();
  const audio = new OfflineAudioContext(
    2,
    Math.round(bars * beat.steps * stepDuration * EXPORT_SAMPLE_RATE),
    EXPORT_SAMPLE_RATE,
  );
  const rack = createEffectsRack(audio, audio.destination, effects);
  try {
    const volume = audio.createGain();
    volume.gain.value = beat.volume;
    volume.connect(rack.input);
    for (let bar = 0; bar < bars; bar++) {
      hits.forEach(({ step, voice }) =>
        scheduleDrumVoice(
          audio,
          volume,
          (bar * beat.steps + step) * stepDuration,
          voice,
        ),
      );
    }
    const rendered = await audio.startRendering();
    return new Blob([encodeWav(rendered)], { type: 'audio/wav' });
  } finally {
    rack.dispose();
  }
};
